package uk.ac.ravensbourne.casevault.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="users") public class UserAccount { @Id private UUID id; @ManyToOne(optional=false) @JoinColumn(name="organisation_id") private Organisation organisation; @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role; @Column(nullable=false) private boolean enabled=true; @Column(name="display_name") private String displayName; @Column(name="deleted_at") private Instant deletedAt; private int failedAttempts; private boolean forcePasswordReset; private Instant lockedUntil,lastLoginAt,createdAt=Instant.now(),updatedAt=Instant.now(),passwordChangedAt=Instant.now(); protected UserAccount(){} public UserAccount(UUID id,Organisation org,String email,String hash,Role role){this.id=id;this.organisation=org;this.email=email;this.passwordHash=hash;this.role=role;} public UUID getId(){return id;} public Organisation getOrganisation(){return organisation;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public Role getRole(){return role;} public boolean isEnabled(){return enabled;} public boolean isLocked(){return lockedUntil!=null&&lockedUntil.isAfter(Instant.now());} public int getFailedAttempts(){return failedAttempts;} public Instant getLastLoginAt(){return lastLoginAt;} public boolean isForcePasswordReset(){return forcePasswordReset;} public String getDisplayName(){return displayName;} public void setDisplayName(String displayName){this.displayName=displayName;} public void registerFailure(){failedAttempts++;if(failedAttempts>=5)lockedUntil=Instant.now().plusSeconds(900);} public void registerSuccess(){failedAttempts=0;lockedUntil=null;lastLoginAt=Instant.now();} public void changePassword(String hash){passwordHash=hash;passwordChangedAt=Instant.now();forcePasswordReset=false;} public void disable(){enabled=false;} public void enable(){enabled=true;} public void requirePasswordReset(){forcePasswordReset=true;} public Instant getDeletedAt(){return deletedAt;} public boolean isDeleted(){return deletedAt!=null;} public void markDeleted(){this.deletedAt=Instant.now();this.enabled=false;this.displayName=null;this.email="deleted-"+id+"@casevault.invalid";this.passwordHash="$deleted$"+UUID.randomUUID();} }
